#define DATA_YAW 0
#define DATA_PITCH 1
#define DATA_Z 2
#define DATA_ZOOM 3
#define DATA_TIME 4
#define DATA_MODE 5
#define DATA_REF 6
#define DATA_GEO 7
#define DATA_TEXT 8

#define GET_DATA(o) texelFetch(iChannel0, ivec2(0, o), 0 ).x
#define GET_DATA_SMOOTH(o) texelFetch(iChannel0, ivec2(0, o), 0 ).y

#define SCALE 1.0

// Reference atmosphere from
// https://github.com/Fewes/MinimalAtmosphere
// Lazy HLSL -> GLSL porting
#define float2 vec2
#define float3 vec3
#define float4 vec4
#define lerp mix

#define PI                 3.14159265359
#define PLANET_RADIUS      6371000.0
#define PLANET_CENTER      float3(0.0, -PLANET_RADIUS, 0.0)
#define ATMOSPHERE_HEIGHT  100000.0
#define RAYLEIGH_HEIGHT    (ATMOSPHERE_HEIGHT * 0.08)
#define MIE_HEIGHT         (ATMOSPHERE_HEIGHT * 0.012)
#define C_RAYLEIGH         (float3(5.802, 13.558, 33.100) * 1e-6)
#define C_MIE              (float3(3.996,  3.996,  3.996) * 1e-6)
#define C_OZONE            (float3(0.650,  1.881,  0.085) * 1e-6)
#define ATMOSPHERE_DENSITY 1.0

float _sq(float x) { return x*x; }
float pow3(float x) { return _sq(x)*x; }
float pow4(float x) { return _sq(_sq(x)); }
float psqrt(float x) { return x > 0.0 ? sqrt(x) : x; }
float saturate(float x) { return clamp(x, 0., 1.); }

float2 SphereIntersection(float3 rayStart, float3 rayDir, float3 sphereCenter, float sphereRadius)
{
	float3 oc = rayStart - sphereCenter;
    float b = dot(oc, rayDir);
    float c = dot(oc, oc) - _sq(sphereRadius);
    float h = _sq(b) - c;
    if (h < 0.0)
    {
        return float2(-1.0, -1.0);
    }
    else
    {
        h = sqrt(h);
        return float2(-b-h, -b+h);
    }
}
float2 PlanetIntersection(float3 rayStart, float3 rayDir)
{
	return SphereIntersection(rayStart, rayDir, PLANET_CENTER, PLANET_RADIUS);
}
float2 AtmosphereIntersection(float3 rayStart, float3 rayDir)
{
	return SphereIntersection(rayStart, rayDir, PLANET_CENTER, PLANET_RADIUS + ATMOSPHERE_HEIGHT);
}
float PhaseR(float costh)
{
	return (1.0+_sq(costh))*0.06;
}
float PhaseM(float costh, float g)
{
	g = min(g, 0.9381);
	float k = 1.55*g-0.55*_sq(g)*g;
	float a = 1.0-_sq(k);
	float b = 12.57*_sq(1.0-k*costh);
	return a/b;
}
float AtmosphereHeight (float3 positionWS)
{
	return distance(positionWS, PLANET_CENTER) - PLANET_RADIUS;
}
float DensityRayleigh (float h)
{
	return exp(-max(0., h / RAYLEIGH_HEIGHT));
}
float DensityMie (float h)
{
	return exp(-max(0., h / MIE_HEIGHT));
}
float DensityOzone (float h)
{
	return max(0., 1. - abs(h - 25000.0) / 15000.0);
}
float3 AtmosphereDensity (float h)
{
	return float3(DensityRayleigh(h), DensityMie(h), DensityOzone(h));
}
float3 IntegrateOpticalDepth (float3 rayStart, float3 rayDir)
{
	float2 intersection = AtmosphereIntersection(rayStart, rayDir);
	float  rayLength    = intersection.y;
	int    sampleCount  = 8;
	float  stepSize     = rayLength / float(sampleCount);
	float3 opticalDepth = vec3(0.);
	for (int i = 0; i < sampleCount; i++)
	{
		float3 localPosition = rayStart + rayDir * (float(i) + 0.5) * stepSize;
		float  localHeight   = AtmosphereHeight(localPosition);
		float3 localDensity  = AtmosphereDensity(localHeight);
		opticalDepth += localDensity * stepSize;
	}
	return opticalDepth;
}
float3 Absorb (float3 opticalDepth)
{
	return exp(-(opticalDepth.x * C_RAYLEIGH + opticalDepth.y * C_MIE * 1.1 + opticalDepth.z * C_OZONE) * ATMOSPHERE_DENSITY);
}
float3 IntegrateScattering (float3 rayStart, float3 rayDir, float rayLength, float3 lightDir, float3 lightColor, float mieG, out float3 transmittance)
{
#ifndef LIGHT_COLOR_IS_RADIANCE
    //lightColor *= PI;
#endif
	float2 intersection = AtmosphereIntersection(rayStart, rayDir);
	rayLength = min(rayLength, intersection.y);
	if (intersection.x > 0.)
	{
		rayStart += rayDir * intersection.x;
		rayLength -= intersection.x;
	}

	float costh  = dot(rayDir, lightDir);
	float phaseR = PhaseR(costh);
	float phaseM = PhaseM(costh, mieG);
	int   sampleCount = 64;
	float3 opticalDepth = vec3(0.);
	float3 rayleigh     = vec3(0.);
	float3 mie          = vec3(0.);
	float  stepSize = rayLength / float(sampleCount);
	for (int i = 0; i < sampleCount; i++)
	{
		float  rayTime = float(i) / float(sampleCount) * rayLength;
		float3 localPosition = rayStart + rayDir * rayTime;
		float  localHeight   = AtmosphereHeight(localPosition);
		float3 localDensity  = AtmosphereDensity(localHeight);
		opticalDepth += localDensity * stepSize;
		float3 viewTransmittance = Absorb(opticalDepth);
		float3 opticalDepthlight  = IntegrateOpticalDepth(localPosition, lightDir);
		float3 lightTransmittance = Absorb(opticalDepthlight);
		rayleigh += viewTransmittance * lightTransmittance * phaseR * localDensity.x * stepSize;
		mie      += viewTransmittance * lightTransmittance * phaseM * localDensity.y * stepSize;
	}

	transmittance = Absorb(opticalDepth);

	return (rayleigh * C_RAYLEIGH + mie * C_MIE) * lightColor;
}

#define HASHSCALE1 .1031
float hash(float p)
{
	vec3 p3  = fract(vec3(p) * HASHSCALE1);
    p3 += dot(p3, p3.yzx + 19.19);
    return fract((p3.x + p3.y) * p3.z);
}

vec3 randomSphereDir(vec2 rnd)
{
	float s = rnd.x*PI*2.;
	float t = rnd.y*2.-1.;
	return vec3(sin(s), cos(s), t) / sqrt(1.0 + t * t);
}
vec3 randomHemisphereDir(vec3 dir, float i)
{
	vec3 v = randomSphereDir( vec2(hash(i+1.), hash(i+2.)) );
	return v * sign(dot(v, dir));
}

// PBR shading from
// https://www.shadertoy.com/view/XlKSDR
float pow5(float x)
{
    float x2 = x * x;
    return x2 * x2 * x;
}
float D_GGX(float linearRoughness, float NoH, const vec3 h)
{
    // Walter et al. 2007, "Microfacet Models for Refraction through Rough Surfaces"
    float oneMinusNoHSquared = 1.0 - NoH * NoH;
    float a = NoH * linearRoughness;
    float k = linearRoughness / (oneMinusNoHSquared + a * a);
    float d = k * k * (1.0 / PI);
    return d;
}
float V_SmithGGXCorrelated(float linearRoughness, float NoV, float NoL)
{
    // Heitz 2014, "Understanding the Masking-Shadowing Function in Microfacet-Based BRDFs"
    float a2 = linearRoughness * linearRoughness;
    float GGXV = NoL * sqrt((NoV - a2 * NoV) * NoV + a2);
    float GGXL = NoV * sqrt((NoL - a2 * NoL) * NoL + a2);
    return 0.5 / (GGXV + GGXL);
}
vec3 F_Schlick(const vec3 f0, float VoH)
{
    // Schlick 1994, "An Inexpensive BRDF Model for Physically-Based Rendering"
    return f0 + (vec3(1.0) - f0) * pow5(1.0 - VoH);
}
float F_Schlick(float f0, float f90, float VoH)
{
    return f0 + (f90 - f0) * pow5(1.0 - VoH);
}
float Fd_Burley(float linearRoughness, float NoV, float NoL, float LoH)
{
    // Burley 2012, "Physically-Based Shading at Disney"
    float f90 = 0.5 + 2.0 * linearRoughness * LoH * LoH;
    float lightScatter = F_Schlick(1.0, f90, NoL);
    float viewScatter  = F_Schlick(1.0, f90, NoV);
    return lightScatter * viewScatter * (1.0 / PI);
}
float Fd_Lambert()
{
    return 1.0 / PI;
}
vec2 PrefilteredDFG_Karis(float roughness, float NoV) {
    // Karis 2014, "Physically Based Material on Mobile"
    const vec4 c0 = vec4(-1.0, -0.0275, -0.572,  0.022);
    const vec4 c1 = vec4( 1.0,  0.0425,  1.040, -0.040);

    vec4 r = roughness * c0 + c1;
    float a004 = min(r.x * r.x, exp2(-9.28 * NoV)) * r.x + r.y;

    return vec2(-1.04, 1.04) * a004 + r.zw;
}

// https://www.shadertoy.com/view/4djSRW
vec3 hash33(vec3 p3)
{
	p3 = fract(p3 * vec3(.1031, .1030, .0973));
    p3 += dot(p3, p3.yxz+33.33);
    return fract((p3.xxy + p3.yxx)*p3.zyx);
}

vec3 Shade(vec2 uv, vec3 diffuse, float roughness, vec3 n, vec3 v, vec3 ld, vec3 lc, vec2 atten, bool ref)
{
    vec3 h = normalize(v + ld);
    float NoV = abs(dot(n, v)) + 1e-5;
    float NoL = saturate(dot(n, ld));
    float NoH = saturate(dot(n, h));
    float LoH = saturate(dot(ld, h));
    float linearRoughness = roughness * roughness;
    float D = D_GGX(linearRoughness, NoH, h);
    float V = V_SmithGGXCorrelated(linearRoughness, NoV, NoL);
    vec3 f0 = vec3(0.04);
    vec3 F = F_Schlick(f0, LoH);
    vec3 Fr = (D * V) * F;
    vec3 Fd = diffuse * Fd_Burley(linearRoughness, NoV, NoL, LoH);

    vec3 refld = reflect(-v, n);

    vec3 lt = VT(ld.y);
    if (ref)
    {
        lt = Absorb(IntegrateOpticalDepth(vec3(0.0), ld));
    }

    vec3 color = (Fd + Fr) * lc * NoL * atten.x * VT(ld.y);

    vec3 ad = vec3(n.x, 0.25, n.z);

    float seed = hash33(vec3(uv, iFrame)).x;
    ad = randomHemisphereDir(n, seed);
    ad.y = max(0.5, ad.y);

    refld = normalize(mix(refld, randomHemisphereDir(n, seed + 1.0), roughness));

    //atten.y *= 0.0; // Disable ambient

    vec3 indirectDiffuse, indirectSpecular;
    if (ref)
    {
        vec3 transmittance;
        indirectDiffuse = IntegrateScattering(vec3(0.0), ad, 1e33, ld, lc, 0.0, transmittance) * PI;
        indirectSpecular = IntegrateScattering(vec3(0.0), refld, 1e33, ld, lc, 0.8, transmittance);
    }
    else
    {
        indirectDiffuse = Sky(ad, ld, 0.0) * PI;
        indirectSpecular = Sky(refld, ld, 0.8);
    }

    vec2 dfg = PrefilteredDFG_Karis(roughness, NoV);
    vec3 specularColor = f0 * dfg.x + dfg.y;
    color += indirectDiffuse * diffuse * Fd_Lambert() * atten.y;
    color += indirectSpecular * specularColor * atten.y;

    //color = vec3(atten.y);

    return color;
}

vec3 TonemapACES(vec3 color)
{
    return (color * (2.51 * color + 0.03)) / (color * (2.43 * color + 0.59) + 0.14);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    float yaw = GET_DATA_SMOOTH(DATA_YAW);
    float pitch = GET_DATA_SMOOTH(DATA_PITCH);
    float z = GET_DATA_SMOOTH(DATA_Z);
    float cam_z = GET_DATA_SMOOTH(DATA_ZOOM);
    float time = GET_DATA_SMOOTH(DATA_TIME);
    bool mode = GET_DATA(DATA_MODE) != 0.0;
    bool showGeo = GET_DATA(DATA_GEO) != 0.0;
    bool showText = GET_DATA(DATA_TEXT) != 0.0;

    vec2 uv = fragCoord / iResolution.xy;
    float aspect = iResolution.x / iResolution.y;

    vec3 rd = normalize(vec3((uv - 0.5) * vec2(aspect, 1.0), cam_z));

    vec3 ld = normalize(vec3(0.5, sin(time), cos(time)));
    vec3 lc = vec3(1, 1, 1);

    float cy = cos(yaw);
    float sy = sin(yaw);
    float cp = cos(pitch);
    float sp = sin(pitch);
    mat3 yawRot = mat3(
        vec3(cy, 0, sy),
        vec3(0, 1, 0),
        vec3(-sy, 0, cy)
    );
    mat3 pitchRot = mat3(
        vec3(1, 0, 0),
        vec3(0, cp, -sp),
        vec3(0, sp, cp)
    );
    mat3 rot = pitchRot * yawRot;

    rd *= rot;

    float scale = SCALE;

    vec3 ro = vec3(0, 0.53 * SCALE, 0) -vec3(0, 0, scale) * rot * z;

    if (mode)
    {
        ro = vec3(0.0);
        vec2 polar = vec2(uv.x * (2.0 * PI), (uv.y - 0.5) * PI);
        rd = vec3(
            cos(polar.x) * cos(polar.y),
            sin(polar.y),
            sin(polar.x) * cos(polar.y)
        );
    }

    vec3 v = -rd;

    vec3 tsm;
    vec3 color = Sky(rd, ld, 0.85, tsm);
    vec3 bg = color;

    bool ref = GET_DATA(DATA_REF) != 0.0 && uv.x > 0.5;

    if (ref)
    {
        color = IntegrateScattering(ro, rd, 1e33, ld, lc, 0.85, tsm);
    }

    //color *= step(0.0, rd.y); // Make "ground" black

    vec3 sc = vec3(0, 0, 0);
    float sr = scale;
    float si = SphereIntersection(ro, rd, sc, sr).x;

    float ph = -scale;
    float pi = ro.y > ph ? -(ro.y - ph) / rd.y : -1.0;
    //pi = PlanetIntersection(ro, rd).x;

    if (showGeo)
    {
        float rl = -1.0;
        if (!mode)
        {
            if (si > 0.0 && (si < pi || pi < 0.0))
            {
                rl = si;
                vec3 albedo = vec3(1.0, 0.0, 0.0);
                vec3 hit = ro + rd * rl;
                vec3 normal = normalize(hit - sc);

                float occ = 1.0 - exp(-(hit.y + scale) / scale);
                color = Shade(fragCoord, albedo, 0.5, normal, v, ld, lc, vec2(1.0, occ), ref);
            }
            else if (pi > 0.0)
            {
                rl = pi;
                vec3 albedo = vec3(0.3, 0.3, 0.3);
                vec3 hit = ro + rd * rl;
                vec3 normal = vec3(0, 1, 0);

                float shadow = step(SphereIntersection(hit, ld, sc, 1.0).x, 0.0);

                for (int i = 0; i < 16; i++)
                {
                    vec3 jitter = hash33(vec3(0,0,i)) * vec3(1, 0, 1) * 0.02;
                    shadow += step(SphereIntersection(hit + jitter, ld, sc, sr).x, 0.0);
                }
                shadow /= 17.0;

                float occ = 1.0 - exp(-length(hit.xz) / scale);
                color = Shade(fragCoord, albedo, 0.8, normal, v, ld, lc, vec2(shadow, occ), ref);
            }
        }
        if (rl > 0.0)
        {
            //rl *= 10.0;
            vec3 hit = ro + rd * rl;
            vec3 sct;
            if (ref)
            {
                sct = IntegrateScattering(ro, rd, rl, ld, lc, 0.85, tsm);
            }
            else
            {
                // WIP attempt at aerial perspective emulation
                float aerialAmount = 1e3;
                vec3 od = vec3(1, 1e-2, 1) * rl * aerialAmount;
                vec3 od2 = smin(od, C_L, C_L * 0.25);
                vec3 lt = VT(ld.y + C_T);
                vec3 vt = VT(od2, C_E);
                vec2 ph = PH(dot(rd, ld), 0.85);
                vec3 R = C_R * od2.x * ph.x * 1.1;
                vec3 M = C_M * od2.y * ph.y * 2.0;

                tsm = VT(od, 1.0);
                sct = (R + M) * lt * vt;

                // Fade to BG
                float fog = exp(-sq(rl) * aerialAmount * 1e-6);
                sct = mix(bg, sct, fog);
                tsm *= fog;
            }
            color = color * tsm + sct;
        }
    }

    //color = vec3(dot(color, vec3(0.333))); // Lum check

    color *= 2.0 * PI; // Exposure
    //color = vec3(1.0) - exp(-color); // Tonemap
    color = TonemapACES(color);
    color = pow(color, vec3(1.0 / 2.2)); // Gamma
    color = color + hash33(vec3(uv,iFrame)) / 255.0;// Dither

    if (showText)
    {
        float text = texture(iChannel3, uv).x;
        color = mix(color, vec3(1.0), text);
    }

    //color = tsm;


    /*
    vec2 planet = PlanetIntersection(ro, rd);
    vec2 atmosphere = AtmosphereIntersection(ro, rd);
    if (!ref)
    {
        atmosphere.y = RL(rd.y);
    }
    color = vec3(exp(-atmosphere.y * 1e-6));
    */

    /*
    color = VT(rd.y);
    color = Absorb(OD(rd.y));
    if (ref)
    {
        color = Absorb(IntegrateOpticalDepth(ro, rd));
    }
    */

    /*
    color = Absorb(OD2(RL(rd.y)).xyz);
    if (ref)
    {
        color = Absorb(IntegrateOpticalDepth(ro, rd).xyz);
    }
    */

    fragColor = vec4(color, 1.0);
}

