#define C_D 1.0 // Density multiplier
#define C_R (vec3(5.802, 13.56, 33.10) * 1e-6 * C_D) // Physical Rayleigh density
#define C_M (vec3(3.996, 3.996, 3.996) * 1e-6 * C_D) // Physical Mie density
#define C_O (vec3(0.650, 1.881, 0.085) * 1e-6 * C_D) // Physical ozone density
#define C_E 0.3 // Extinction fraction (raymarch approximation)
#define C_T 0.1 // Twilight offset
#define C_L 1e5 // Optical depth limit (makes "ground" less orange)
float sq(float x) { return x*x; }
vec3 smin(vec3 a, float b, float k ) // https://iquilezles.org/articles/smin/
{
    k *= 1.0/(1.0-sqrt(0.5)); vec3 h = max(k-abs(a-b), 0.0)/k;
    const float b2 = 13.0/4.0 - 4.0*sqrt(0.5);
    const float b3 =  3.0/4.0 - 1.0*sqrt(0.5);
    return min(a,b) - k*h*h*(h*b3*(h-4.0)+b2);
}
vec2 PH(float costh, float g) // Rayleigh / Mie phase
{
	g = min(g, 0.9381); float k = 1.55*g-0.55*sq(g)*g;
	float a = 1.0-sq(k); float b = 12.57*sq(1.0-k*costh);
    return vec2((1.0+sq(costh))*0.06, a/b);
}
float RL(float zn) // Atmosphere exit dist approximation
{
    float h = max(0.0, 1.0 - zn); float h2 = sq(h);
    float h4 = sq(h2); float h8 = sq(h4); float h16 = sq(h8);
    return 1e5 + h*2e4 + h2*3e5 + h4*4e4 + h8*5e5 + h16*5e4;
}
vec3 OD(float rl) // Optical depth approximation
{
    float rl2 = sq(rl); float rl4 = sq(rl2); float rl8 = sq(rl4);
    return vec3(rl*7e-2   + rl2*2e-8 + rl4*1.5e-19,
                rl*1e-3   + rl2*1e-9 + rl4*1e-19,
                rl*1.5e-1 + rl2*2e-8 + rl4*1e-19);
}
vec3 VT(vec3 od, float m) // View transmittance
{
    return exp(-(od.x*C_R + od.y*C_M*1.1 + od.z*C_O) * m);
}
vec3 VT(float zn) { return VT(OD(RL(zn)), 1.0); }
vec3 Sky(vec3 rd, vec3 ld, float g, out vec3 tsm) // Main sky function
{
    float rl = RL(rd.y);
    float ldp = sqrt(max(0.0, ld.y));
    vec2 ph = PH(dot(rd, ld), g);
    vec3 od = smin(OD(rl), C_L, C_L * 0.25);
    float e = C_E / (0.2 + 0.8 * ldp);
    vec3 vt = VT(od, e);
    vec3 lt = VT(ld.y + C_T);
    tsm = VT(OD(rl), 1.0);
    vec3 R = C_R * od.x * ph.x * 1.1;
    vec3 M = C_M * od.y * ph.y * 2.0;
    return (R + M) * lt * vt;
}
vec3 Sky(vec3 rd, vec3 ld, float g) { vec3 foo; return Sky(rd, ld, g, foo); }

// Controls buffer

