void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    int type = int(fragCoord.y);
    vec4 data = texelFetch(iChannel0, ivec2(0, type), 0);
    bool initialize = iFrame == 0;

    bool shift = texelFetch(iChannel1, ivec2(KEY_LSHIFT, 0), 0).x != 0.0;
    bool space = texelFetch(iChannel1, ivec2(KEY_SPACE, 0), 0).x != 0.0;
    bool r = texelFetch(iChannel1, ivec2(KEY_R, 0), 0).x != 0.0;
    bool g = texelFetch(iChannel1, ivec2(KEY_G, 0), 0).x != 0.0;
    bool h = texelFetch(iChannel1, ivec2(KEY_H, 0), 0).x != 0.0;

    vec2 mouse = iMouse.xy / iResolution.xy;
    float yaw = (mouse.x - 0.5) * PI * 2.0;
    float pitch = -(mouse.y - 0.5) * PI * 2.0;

    if (type == DATA_YAW)
    {
        if (initialize || data.z == 0.0)
        {
            data = vec4(YAW_DEFAULT, YAW_DEFAULT, mouse.x, 0);
        }
        float yawDelta = (mouse.x - data.z) * step(0.0, data.w);
        data.x -= yawDelta * YAW_SENS;
        data.y = mix(data.y, data.x, iTimeDelta / YAW_SMOOTHING);
        data.z = mouse.x;
        data.w = iMouse.z;
    }

    if (type == DATA_PITCH)
    {
        if (initialize || data.z == 0.0)
        {
            data = vec4(PITCH_DEFAULT, PITCH_DEFAULT, mouse.y, 0);
        }
        float delta = (mouse.y - data.z) * step(0.0, data.w);
        data.x -= delta * PITCH_SENS;
        data.x = clamp(data.x, PITCH_MIN, PITCH_MAX);
        data.y = mix(data.y, data.x, iTimeDelta / PITCH_SMOOTHING);
        data.z = mouse.y;
        data.w = iMouse.z;
    }

    if (type == DATA_Z)
    {
        if (initialize)
        {
            data = vec4(Z_DEFAULT);
        }
        if (!shift)
        {
            data.x -= texelFetch(iChannel1, ivec2(KEY_W, 0), 0 ).x * Z_SENS;
            data.x += texelFetch(iChannel1, ivec2(KEY_S, 0), 0 ).x * Z_SENS;
        }
        data.x = clamp(data.x, Z_MIN, Z_MAX);
        data.y = mix(data.y, data.x, iTimeDelta / Z_SMOOTHING);
    }

    if (type == DATA_ZOOM)
    {
        if (initialize)
        {
            data = vec4(ZOOM_DEFAULT);
        }
        if (shift)
        {
            float zoomMod = 1.0;
            zoomMod -= texelFetch(iChannel1, ivec2(KEY_S, 0), 0 ).x * ZOOM_SENS;
            zoomMod += texelFetch(iChannel1, ivec2(KEY_W, 0), 0 ).x * ZOOM_SENS;
            data.x *= zoomMod;
        }
        data.x = clamp(data.x, ZOOM_MIN, ZOOM_MAX);
        data.y = mix(data.y, data.x, iTimeDelta / ZOOM_SMOOTHING);
    }

    if (type == DATA_TIME)
    {
        if (initialize)
        {
            data = vec4(TIME_DEFAULT);
        }
        data.x -= texelFetch(iChannel1, ivec2(KEY_A, 0), 0 ).x * TIME_SENS;
        data.x += texelFetch(iChannel1, ivec2(KEY_D, 0), 0 ).x * TIME_SENS;
        data.y = mix(data.y, data.x, iTimeDelta / TIME_SMOOTHING);
    }

    if (type == DATA_MODE)
    {
        if (initialize)
        {
            data = vec4(MODE_DEFAULT);
        }
        if (space && data.z == 0.0)
        {
            data.x = 1.0 - data.x;
        }
        data.z = space ? 1.0 : 0.0;
    }

    if (type == DATA_REF)
    {
        if (initialize)
        {
            data = vec4(REF_DEFAULT);
        }
        if (r && data.z == 0.0)
        {
            data.x = 1.0 - data.x;
        }
        data.z = r ? 1.0 : 0.0;
    }

    if (type == DATA_GEO)
    {
        if (initialize)
        {
            data = vec4(GEO_DEFAULT);
        }
        if (g && data.z == 0.0)
        {
            data.x = 1.0 - data.x;
        }
        data.z = g ? 1.0 : 0.0;
    }

    if (type == DATA_TEXT)
    {
        if (initialize)
        {
            data = vec4(TEXT_DEFAULT);
        }
        if (h && data.z == 0.0)
        {
            data.x = 1.0 - data.x;
        }
        data.z = h ? 1.0 : 0.0;
    }

    fragColor = data;
}
